import { useMutation } from '@tanstack/react-query';
import { ResultSearchDTO, ResultSearchResponseDTO } from '~/entities/exchange/api/dtos/types';
import { exchangeApi } from '~/entities/exchange/api/exchange-api';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';

export const useResultSearchMutation = (
  options?: MutationOptions<ResultSearchDTO, CBDCAxiosError, ResultSearchResponseDTO>,
) => {
  const mutation = useMutation<ResultSearchResponseDTO, CBDCAxiosError, ResultSearchDTO>({
    ...options,
    mutationFn: exchangeApi.resultSearch,
  });

  return {
    ...mutation,
  };
};
